import 'package:sqflite/sqflite.dart';

abstract final class SchemaBuilder {
  static Future<void> build(DatabaseExecutor db) async {
    final statements = <String>[
      '''CREATE TABLE branches (id INTEGER PRIMARY KEY AUTOINCREMENT, uuid TEXT NOT NULL UNIQUE, branch_id INTEGER, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, is_deleted INTEGER NOT NULL DEFAULT 0 CHECK(is_deleted IN(0,1)), sync_status TEXT NOT NULL DEFAULT 'LOCAL', sync_version INTEGER NOT NULL DEFAULT 1, code TEXT NOT NULL UNIQUE, name_ar TEXT NOT NULL, name_en TEXT, address TEXT, phone TEXT, license_no TEXT, is_main INTEGER NOT NULL DEFAULT 0 CHECK(is_main IN(0,1)), is_active INTEGER NOT NULL DEFAULT 1 CHECK(is_active IN(0,1)))''',
      '''CREATE TABLE users (id INTEGER PRIMARY KEY AUTOINCREMENT, uuid TEXT NOT NULL UNIQUE, branch_id INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, is_deleted INTEGER NOT NULL DEFAULT 0, sync_status TEXT NOT NULL DEFAULT 'LOCAL', sync_version INTEGER NOT NULL DEFAULT 1, username TEXT NOT NULL UNIQUE, full_name TEXT NOT NULL, role_code TEXT NOT NULL CHECK(role_code IN('OWNER','MANAGER','PHARMACIST','CASHIER','ACCOUNTANT')), password_hash TEXT NOT NULL, manager_pin_hash TEXT, is_active INTEGER NOT NULL DEFAULT 1 CHECK(is_active IN(0,1)), FOREIGN KEY(branch_id) REFERENCES branches(id))''',
      '''CREATE TABLE system_settings (id INTEGER PRIMARY KEY AUTOINCREMENT, uuid TEXT NOT NULL UNIQUE, branch_id INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, is_deleted INTEGER NOT NULL DEFAULT 0, sync_status TEXT NOT NULL DEFAULT 'LOCAL', sync_version INTEGER NOT NULL DEFAULT 1, setting_no INTEGER NOT NULL UNIQUE CHECK(setting_no BETWEEN 1 AND 35), setting_key TEXT NOT NULL UNIQUE, group_code TEXT NOT NULL, value_type TEXT NOT NULL, value_text TEXT, default_text TEXT, label_ar TEXT NOT NULL, requires_manager INTEGER NOT NULL DEFAULT 0 CHECK(requires_manager IN(0,1)), FOREIGN KEY(branch_id) REFERENCES branches(id))''',
      '''CREATE TABLE number_sequences (id INTEGER PRIMARY KEY AUTOINCREMENT, uuid TEXT NOT NULL UNIQUE, branch_id INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, is_deleted INTEGER NOT NULL DEFAULT 0, sync_status TEXT NOT NULL DEFAULT 'LOCAL', sync_version INTEGER NOT NULL DEFAULT 1, doc_type TEXT NOT NULL, prefix TEXT NOT NULL, year INTEGER NOT NULL, last_no INTEGER NOT NULL DEFAULT 0 CHECK(last_no>=0), pad_length INTEGER NOT NULL DEFAULT 6 CHECK(pad_length BETWEEN 1 AND 18), UNIQUE(branch_id,doc_type,year), FOREIGN KEY(branch_id) REFERENCES branches(id))''',
      '''CREATE TABLE active_ingredients (id INTEGER PRIMARY KEY AUTOINCREMENT, uuid TEXT NOT NULL UNIQUE, branch_id INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, is_deleted INTEGER NOT NULL DEFAULT 0, sync_status TEXT NOT NULL DEFAULT 'LOCAL', sync_version INTEGER NOT NULL DEFAULT 1, inn_name TEXT NOT NULL UNIQUE, name_ar TEXT, chemical_formula TEXT, atc_code_default TEXT)''',
      '''CREATE TABLE drug_categories (id INTEGER PRIMARY KEY AUTOINCREMENT, uuid TEXT NOT NULL UNIQUE, branch_id INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, is_deleted INTEGER NOT NULL DEFAULT 0, sync_status TEXT NOT NULL DEFAULT 'LOCAL', sync_version INTEGER NOT NULL DEFAULT 1, parent_id INTEGER, code TEXT NOT NULL UNIQUE, name_ar TEXT NOT NULL, name_en TEXT, atc_prefix TEXT, is_antibiotic INTEGER NOT NULL DEFAULT 0 CHECK(is_antibiotic IN(0,1)), FOREIGN KEY(parent_id) REFERENCES drug_categories(id))''',
      '''CREATE TABLE manufacturers (id INTEGER PRIMARY KEY AUTOINCREMENT, uuid TEXT NOT NULL UNIQUE, branch_id INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, is_deleted INTEGER NOT NULL DEFAULT 0, sync_status TEXT NOT NULL DEFAULT 'LOCAL', sync_version INTEGER NOT NULL DEFAULT 1, name_ar TEXT NOT NULL, name_en TEXT, country TEXT, UNIQUE(name_ar,country))''',
      _drugTable,
      '''CREATE TABLE parties (id INTEGER PRIMARY KEY AUTOINCREMENT, uuid TEXT NOT NULL UNIQUE, branch_id INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, is_deleted INTEGER NOT NULL DEFAULT 0, sync_status TEXT NOT NULL DEFAULT 'LOCAL', sync_version INTEGER NOT NULL DEFAULT 1, party_type TEXT NOT NULL CHECK(party_type IN('CUSTOMER','SUPPLIER','EMPLOYEE','PARTNER','REPRESENTATIVE')), code TEXT NOT NULL UNIQUE, name_ar TEXT NOT NULL, phone TEXT, address TEXT, national_id TEXT, credit_limit REAL NOT NULL DEFAULT 0 CHECK(credit_limit>=0), payment_terms_days INTEGER NOT NULL DEFAULT 0 CHECK(payment_terms_days>=0), is_chronic_patient INTEGER NOT NULL DEFAULT 0, is_blocked INTEGER NOT NULL DEFAULT 0, opening_alayh REAL NOT NULL DEFAULT 0 CHECK(opening_alayh>=0), opening_lah REAL NOT NULL DEFAULT 0 CHECK(opening_lah>=0))''',
      '''CREATE TABLE chart_of_accounts (id INTEGER PRIMARY KEY AUTOINCREMENT, uuid TEXT NOT NULL UNIQUE, branch_id INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, is_deleted INTEGER NOT NULL DEFAULT 0, sync_status TEXT NOT NULL DEFAULT 'LOCAL', sync_version INTEGER NOT NULL DEFAULT 1, code TEXT NOT NULL UNIQUE, name_ar TEXT NOT NULL, acc_type TEXT NOT NULL)''',
      '''CREATE TABLE journal_entries (id INTEGER PRIMARY KEY AUTOINCREMENT, uuid TEXT NOT NULL UNIQUE, branch_id INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, is_deleted INTEGER NOT NULL DEFAULT 0, sync_status TEXT NOT NULL DEFAULT 'LOCAL', sync_version INTEGER NOT NULL DEFAULT 1, entry_no TEXT NOT NULL UNIQUE, entry_date TEXT NOT NULL, description TEXT NOT NULL, source_type TEXT NOT NULL, source_id INTEGER, is_posted INTEGER NOT NULL DEFAULT 1 CHECK(is_posted IN(0,1)))''',
      '''CREATE TABLE journal_lines (id INTEGER PRIMARY KEY AUTOINCREMENT, uuid TEXT NOT NULL UNIQUE, branch_id INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, is_deleted INTEGER NOT NULL DEFAULT 0, sync_status TEXT NOT NULL DEFAULT 'LOCAL', sync_version INTEGER NOT NULL DEFAULT 1, journal_entry_id INTEGER NOT NULL, account_id INTEGER NOT NULL, party_id INTEGER, dr_amount REAL NOT NULL DEFAULT 0 CHECK(dr_amount>=0), cr_amount REAL NOT NULL DEFAULT 0 CHECK(cr_amount>=0), memo TEXT, CHECK((dr_amount>0 AND cr_amount=0) OR (cr_amount>0 AND dr_amount=0)), FOREIGN KEY(journal_entry_id) REFERENCES journal_entries(id), FOREIGN KEY(account_id) REFERENCES chart_of_accounts(id), FOREIGN KEY(party_id) REFERENCES parties(id))''',
      '''CREATE TABLE lah_alayh_ledger (id INTEGER PRIMARY KEY AUTOINCREMENT, uuid TEXT NOT NULL UNIQUE, branch_id INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, is_deleted INTEGER NOT NULL DEFAULT 0, sync_status TEXT NOT NULL DEFAULT 'LOCAL', sync_version INTEGER NOT NULL DEFAULT 1, party_id INTEGER NOT NULL, entry_date TEXT NOT NULL, entry_type TEXT NOT NULL, alayh_amount REAL NOT NULL DEFAULT 0 CHECK(alayh_amount>=0), lah_amount REAL NOT NULL DEFAULT 0 CHECK(lah_amount>=0), doc_type TEXT NOT NULL, doc_id INTEGER, statement_ar TEXT NOT NULL, journal_entry_id INTEGER, CHECK((alayh_amount>0 AND lah_amount=0) OR (lah_amount>0 AND alayh_amount=0)), FOREIGN KEY(party_id) REFERENCES parties(id), FOREIGN KEY(journal_entry_id) REFERENCES journal_entries(id))''',
      '''CREATE TABLE cash_accounts (id INTEGER PRIMARY KEY AUTOINCREMENT, uuid TEXT NOT NULL UNIQUE, branch_id INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, is_deleted INTEGER NOT NULL DEFAULT 0, sync_status TEXT NOT NULL DEFAULT 'LOCAL', sync_version INTEGER NOT NULL DEFAULT 1, code TEXT NOT NULL UNIQUE, name_ar TEXT NOT NULL, account_kind TEXT NOT NULL CHECK(account_kind IN('CASHIER_DRAWER','MAIN_SAFE','WALLET','BANK')), wallet_provider TEXT CHECK(wallet_provider IN('JAWALI','JAIB','FLOUSK','KURAIMI','OTHER')), wallet_phone TEXT, gl_account_id INTEGER, current_balance REAL NOT NULL DEFAULT 0, FOREIGN KEY(gl_account_id) REFERENCES chart_of_accounts(id))''',
      '''CREATE TABLE vouchers (id INTEGER PRIMARY KEY AUTOINCREMENT, uuid TEXT NOT NULL UNIQUE, branch_id INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, is_deleted INTEGER NOT NULL DEFAULT 0, sync_status TEXT NOT NULL DEFAULT 'LOCAL', sync_version INTEGER NOT NULL DEFAULT 1, voucher_no TEXT NOT NULL UNIQUE, voucher_type TEXT NOT NULL CHECK(voucher_type IN('RECEIPT','PAYMENT','SETTLEMENT')), voucher_date TEXT NOT NULL, party_id INTEGER, cash_account_id INTEGER, amount REAL NOT NULL CHECK(amount>0), method TEXT NOT NULL CHECK(method IN('CASH','WALLET','BANK','OFFSET')), wallet_ref_no TEXT, description TEXT, journal_entry_id INTEGER, FOREIGN KEY(party_id) REFERENCES parties(id), FOREIGN KEY(cash_account_id) REFERENCES cash_accounts(id), FOREIGN KEY(journal_entry_id) REFERENCES journal_entries(id))''',
      '''CREATE TABLE sales_invoices (id INTEGER PRIMARY KEY AUTOINCREMENT, uuid TEXT NOT NULL UNIQUE, branch_id INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, is_deleted INTEGER NOT NULL DEFAULT 0, sync_status TEXT NOT NULL DEFAULT 'LOCAL', sync_version INTEGER NOT NULL DEFAULT 1, invoice_no TEXT NOT NULL UNIQUE, invoice_date TEXT NOT NULL, cashier_user_id INTEGER NOT NULL, customer_party_id INTEGER, sale_type TEXT NOT NULL CHECK(sale_type IN('CASH','CREDIT','MIXED')), status TEXT NOT NULL CHECK(status IN('HELD','COMPLETED','VOIDED')), hold_label TEXT, subtotal REAL NOT NULL DEFAULT 0, discount_pct REAL NOT NULL DEFAULT 0, discount_amount REAL NOT NULL DEFAULT 0, rounding_diff REAL NOT NULL DEFAULT 0, net_total REAL NOT NULL DEFAULT 0, paid_total REAL NOT NULL DEFAULT 0, remaining_alayh REAL NOT NULL DEFAULT 0, total_cost REAL NOT NULL DEFAULT 0, journal_entry_id INTEGER, FOREIGN KEY(cashier_user_id) REFERENCES users(id), FOREIGN KEY(customer_party_id) REFERENCES parties(id), FOREIGN KEY(journal_entry_id) REFERENCES journal_entries(id))''',
      '''CREATE TABLE sales_invoice_items (id INTEGER PRIMARY KEY AUTOINCREMENT, uuid TEXT NOT NULL UNIQUE, branch_id INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, is_deleted INTEGER NOT NULL DEFAULT 0, sync_status TEXT NOT NULL DEFAULT 'LOCAL', sync_version INTEGER NOT NULL DEFAULT 1, invoice_id INTEGER NOT NULL, drug_id INTEGER NOT NULL, sell_unit TEXT NOT NULL CHECK(sell_unit IN('PACK','STRIP','UNIT')), qty_in_sell_unit REAL NOT NULL CHECK(qty_in_sell_unit>0), qty_units INTEGER NOT NULL CHECK(qty_units>0), unit_price_sell_unit REAL NOT NULL, line_discount_amount REAL NOT NULL DEFAULT 0, line_total REAL NOT NULL, line_cost REAL NOT NULL, FOREIGN KEY(invoice_id) REFERENCES sales_invoices(id), FOREIGN KEY(drug_id) REFERENCES drugs(id))''',
      '''CREATE TABLE sales_payments (id INTEGER PRIMARY KEY AUTOINCREMENT, uuid TEXT NOT NULL UNIQUE, branch_id INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, is_deleted INTEGER NOT NULL DEFAULT 0, sync_status TEXT NOT NULL DEFAULT 'LOCAL', sync_version INTEGER NOT NULL DEFAULT 1, invoice_id INTEGER NOT NULL, cash_account_id INTEGER NOT NULL, method TEXT NOT NULL CHECK(method IN('CASH','WALLET','BANK')), amount REAL NOT NULL CHECK(amount>0), wallet_ref_no TEXT, wallet_sender_phone TEXT, FOREIGN KEY(invoice_id) REFERENCES sales_invoices(id), FOREIGN KEY(cash_account_id) REFERENCES cash_accounts(id))''',
    ];
    for (final sql in statements) { await db.execute(sql); }
    await db.execute('CREATE INDEX idx_drugs_search ON drugs(trade_name_ar, scientific_name, barcode_local, barcode_international)');
    await db.execute('CREATE INDEX idx_party_ledger ON lah_alayh_ledger(party_id, entry_date, id)');
    await db.execute('CREATE INDEX idx_invoice_date ON sales_invoices(invoice_date, status)');
    await db.execute('CREATE INDEX idx_drug_stock ON drugs(stock_total_units, min_stock_units)');
    await db.execute('''CREATE VIEW v_party_balance AS
      SELECT p.id AS party_id, p.branch_id,
      p.opening_alayh + COALESCE(SUM(l.alayh_amount),0) AS total_alayh,
      p.opening_lah + COALESCE(SUM(l.lah_amount),0) AS total_lah,
      (p.opening_alayh + COALESCE(SUM(l.alayh_amount),0)) - (p.opening_lah + COALESCE(SUM(l.lah_amount),0)) AS net,
      CASE WHEN (p.opening_alayh + COALESCE(SUM(l.alayh_amount),0)) > (p.opening_lah + COALESCE(SUM(l.lah_amount),0)) THEN 'ALAYH'
      WHEN (p.opening_lah + COALESCE(SUM(l.lah_amount),0)) > (p.opening_alayh + COALESCE(SUM(l.alayh_amount),0)) THEN 'LAH' ELSE 'ZERO' END AS balance_side,
      ABS((p.opening_alayh + COALESCE(SUM(l.alayh_amount),0)) - (p.opening_lah + COALESCE(SUM(l.lah_amount),0))) AS balance_abs
      FROM parties p LEFT JOIN lah_alayh_ledger l ON l.party_id=p.id AND l.is_deleted=0
      WHERE p.is_deleted=0 GROUP BY p.id''');
  }

  static const String _drugTable = '''CREATE TABLE drugs (
    id INTEGER PRIMARY KEY AUTOINCREMENT, uuid TEXT NOT NULL UNIQUE, branch_id INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, is_deleted INTEGER NOT NULL DEFAULT 0, sync_status TEXT NOT NULL DEFAULT 'LOCAL', sync_version INTEGER NOT NULL DEFAULT 1,
    internal_code TEXT NOT NULL UNIQUE, is_active INTEGER NOT NULL DEFAULT 1, completeness_pct REAL NOT NULL DEFAULT 0 CHECK(completeness_pct BETWEEN 0 AND 100),
    trade_name_ar TEXT NOT NULL, trade_name_en TEXT, manufacturer_id INTEGER, scientific_name TEXT, active_ingredient_id INTEGER, ingredients_json TEXT NOT NULL DEFAULT '[]', chemical_composition TEXT,
    category_id INTEGER, therapeutic_class TEXT, pharmacologic_class TEXT, atc_code TEXT,
    dosage_form TEXT NOT NULL DEFAULT 'OTHER' CHECK(dosage_form IN('TABLET','CAPSULE','SYRUP','SUSPENSION','DROPS','INJECTION','CREAM','OINTMENT','INHALER','SUPPOSITORY','SACHET','OTHER')),
    strength_text TEXT, strength_value REAL, strength_unit TEXT, route TEXT NOT NULL DEFAULT 'OTHER' CHECK(route IN('ORAL','IV','IM','SC','TOPICAL','OPHTHALMIC','INHALATION','RECTAL','OTHER')), is_strip_based INTEGER NOT NULL DEFAULT 0,
    indications TEXT, dosage_administration TEXT, adult_dose_min_mg REAL, adult_dose_max_mg_per_day REAL, dose_frequency_text TEXT, take_with_food TEXT NOT NULL DEFAULT 'ANY' CHECK(take_with_food IN('BEFORE','WITH','AFTER','ANY')), label_dose_text_ar TEXT,
    contraindications TEXT, contraindications_json TEXT DEFAULT '[]', warnings_precautions TEXT, black_box_warning TEXT, warnings_json TEXT DEFAULT '[]',
    interactions_summary TEXT, has_critical_interactions INTEGER NOT NULL DEFAULT 0, side_effects_common TEXT, side_effects_serious TEXT,
    strips_per_pack INTEGER NOT NULL DEFAULT 1 CHECK(strips_per_pack>=1), units_per_strip INTEGER NOT NULL DEFAULT 1 CHECK(units_per_strip>=1), units_per_pack INTEGER NOT NULL DEFAULT 1 CHECK(units_per_pack>=1),
    cost_price_pack REAL NOT NULL DEFAULT 0 CHECK(cost_price_pack>=0), last_purchase_cost_pack REAL NOT NULL DEFAULT 0, sell_price_pack REAL NOT NULL DEFAULT 0, sell_price_strip REAL NOT NULL DEFAULT 0, sell_price_unit REAL NOT NULL DEFAULT 0,
    strip_price_mode TEXT NOT NULL DEFAULT 'AUTO' CHECK(strip_price_mode IN('AUTO','MANUAL')), profit_margin_pct REAL NOT NULL DEFAULT 0, public_price_pack REAL NOT NULL DEFAULT 0, tax_rate_pct REAL NOT NULL DEFAULT 0,
    min_stock_units INTEGER NOT NULL DEFAULT 0 CHECK(min_stock_units>=0), reorder_qty_packs INTEGER NOT NULL DEFAULT 0, stock_total_units INTEGER NOT NULL DEFAULT 0 CHECK(stock_total_units>=0),
    min_age_months INTEGER, max_age_months INTEGER, allowed_populations_json TEXT DEFAULT '[]',
    hepatic_status TEXT NOT NULL DEFAULT 'UNKNOWN' CHECK(hepatic_status IN('SAFE','ADJUST','AVOID','CONTRAINDICATED','UNKNOWN')), hepatic_notes TEXT,
    renal_status TEXT NOT NULL DEFAULT 'UNKNOWN' CHECK(renal_status IN('SAFE','ADJUST','AVOID','CONTRAINDICATED','UNKNOWN')), renal_notes TEXT, is_nephrotoxic INTEGER NOT NULL DEFAULT 0,
    geriatric_status TEXT NOT NULL DEFAULT 'UNKNOWN' CHECK(geriatric_status IN('SAFE','ADJUST','AVOID','UNKNOWN')), geriatric_notes TEXT, beers_criteria TEXT, geriatric_age_threshold INTEGER DEFAULT 65,
    pediatric_status TEXT NOT NULL DEFAULT 'UNKNOWN' CHECK(pediatric_status IN('SAFE','ADJUST','AVOID','CONTRAINDICATED','UNKNOWN')), pediatric_notes TEXT, ped_dose_mg_per_kg_min REAL, ped_dose_mg_per_kg_max REAL, ped_max_daily_mg_per_kg REAL, ped_doses_per_day INTEGER, neonate_allowed INTEGER NOT NULL DEFAULT 0,
    pregnancy_category TEXT NOT NULL DEFAULT 'UNKNOWN' CHECK(pregnancy_category IN('A','B','C','D','X','N','UNKNOWN')), pregnancy_notes TEXT, pregnancy_trimester_json TEXT DEFAULT '{}',
    lactation_risk TEXT NOT NULL DEFAULT 'UNKNOWN' CHECK(lactation_risk IN('L1','L2','L3','L4','L5','UNKNOWN')), lactation_notes TEXT,
    storage_conditions TEXT, storage_temp_min_c REAL, storage_temp_max_c REAL, requires_refrigeration INTEGER NOT NULL DEFAULT 0, protect_from_light INTEGER NOT NULL DEFAULT 0, barcode_international TEXT UNIQUE, barcode_local TEXT UNIQUE, registration_no TEXT, is_controlled INTEGER NOT NULL DEFAULT 0, controlled_schedule TEXT, requires_prescription INTEGER NOT NULL DEFAULT 0, prescription_restricted INTEGER NOT NULL DEFAULT 0, is_antibiotic INTEGER NOT NULL DEFAULT 0,
    FOREIGN KEY(branch_id) REFERENCES branches(id), FOREIGN KEY(manufacturer_id) REFERENCES manufacturers(id), FOREIGN KEY(active_ingredient_id) REFERENCES active_ingredients(id), FOREIGN KEY(category_id) REFERENCES drug_categories(id))''';
}
